#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
      int t;
      cin >> t;
      
      while(t--){
          int n;
          cin>> n;
          
          vector<long long> a (3 * n);
          
          for(auto &x : a) cin>> x;
          
          sort(a.rbegin(), a.rend());
          
          vector<long long> pre(3 * n + 1);
          
          for(int i=0; i< 3* n; i++){
              pre[i+1] = pre[i] + a[i];
          }
          
          long long ans=0;
          
          for(int p=0; p<=n; p++){
             auto f = [&](int q){
                 int x = p + 2 * q;
                 int y = 3 * n - 2 * p - q;
                 return 2 * pre[p] + pre[x] + 3 * pre[y];
             };
             
             
             int l = 0, r = n-p;
             
             while(l < r){
                 int m = (l+r)/2;
                 
                 if(f(m) < f(m+1)){
                     l = m+1;
                 }else r = m;
             }
             
             ans = max(ans,f(l));
          }
            cout<<ans<<endl;
      }
}
